1: <!DOCTYPE html>
2: <html lang="ru">
3: <head>
4:   <meta charset="UTF-8" />
5:   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
6:   <title>Flappy Bird — DDD Architecture</title>
7:   <style>
8:     * { box-sizing: border-box; margin: 0; padding: 0; }
9:     body {
10:       font-family: system-ui, -apple-system, sans-serif;
11:       background: #2d2d2d;
12:       display: flex;
13:       justify-content: center;
14:       align-items: center;
15:       min-height: 100vh;
16:       margin: 0;
17:     }
18:     .game-wrapper {
19:       background: #1a1a1a;
20:       padding: 20px;
21:       border-radius: 12px;
22:       box-shadow: 0 8px 32px rgba(0,0,0,0.5);
23:     }
24:     .game-area {
25:       position: relative;
26:     }
27:     canvas {
28:       display: block;
29:       background: #70c5ce;
30:       border-radius: 8px;
31:       width: 400px;
32:       height: 500px;
33:     }
34:     .overlay {
35:       position: absolute;
36:       top: 0; left: 0; right: 0; bottom: 0;
37:       background: rgba(0,0,0,0.7);
38:       display: flex;
39:       flex-direction: column;
40:       align-items: center;
41:       justify-content: center;
