46:     .hidden { display: none !important; }
47: 
48:     #nickname-screen { z-index: 10; }
49:     #gameover-screen { z-index: 20; }
50: 
51:     .overlay input {
52:       padding: 10px 16px;
53:       border: none;
54:       border-radius: 6px;
55:       font-size: 16px;
56:       text-align: center;
