70:     .overlay button:hover { background: #e0b535; }
71:     .overlay button:disabled { opacity: 0.5; cursor: not-allowed; }
72: 
73:     #leaderboard-container {
74:       background: rgba(255,255,255,0.9);
75:       color: #1a1a1a;
76:       padding: 12px 20px;
