94: </head>
95: <body>
96:   <div class="game-wrapper">
97:     <div class="game-area">
98:       <canvas id="game-canvas" width="400" height="500"></canvas>
99: 
100:       <!-- Nickname Screen -->
101:       <div id="nickname-screen" class="overlay">
102:         <h2>🐦 Flappy Bird</h2>
103:         <p style="color:#ccc;font-size:14px;">Введите никнейм для таблицы лидеров</p>
104:         <input id="nickname-input" type="text" maxlength="16" placeholder="Ваш никнейм" />
105:         <button id="nickname-btn">Play!</button>
106:       </div>
107: 
108:       <!-- Game Over Screen -->
109:       <div id="gameover-screen" class="overlay hidden">
110:         <h2>💀 Game Over</h2>
111:         <p id="final-score" style="font-size:24px;font-weight:bold;">Score: 0</p>
112:         <div id="leaderboard-container"></div>
113:         <button id="save-score-btn">💾 Save Score</button>
114:         <button id="restart-btn">🔄 Play Again</button>
115:       </div>
116:     </div>
117:     <div class="game-info">
118:       Flappy Bird · DDD/Clean Architecture · Space / Click to jump
119:     </div>
120:   </div>
121: 
122:   <script type="module">
123:     import { createApp } from './src/presentation/app.js';
124:     import { createLocalLeaderboard } from './src/infrastructure/LocalLeaderboard.js';
125: 
126:     const canvas = document.getElementById('game-canvas');
127:     const uiRoot = document.querySelector('.game-area');
128:     const gameOverContainer = document.getElementById('gameover-screen');
129: 
130:     const { readable, writable } = createLocalLeaderboard();
131: 
132:     const app = createApp({
133:       canvas,
134:       uiRoot,
135:       gameOverContainer,
136:       writer: writable,
137:       reader: readable,
138:     });
139:   </script>
140: </body>
141: </html>

1: /**
2:  * @file Основной экран: меню → игра → Game Over → лидерборд
3:  */
4: 
5: import { createFlappyBird } from '../games/FlappyBird.js';
6: import { createSaveScore } from '../application/SaveScore.js';
7: import { createGetLeaderboard } from '../application/GetLeaderboard.js';
8: 
9: /**
10:  * @param {object} deps
11:  * @param {HTMLCanvasElement} deps.canvas
12:  * @param {HTMLDivElement} deps.uiRoot — корневой div для вставки меню/лидерборда
13:  * @param {HTMLElement} deps.gameOverContainer — контейнер для GameOver-скрина
14:  * @param {import('../../domain/contracts.js').IWritableLeaderboard} deps.writer
15:  * @param {import('../../domain/contracts.js').IReadableLeaderboard} deps.reader
16:  */
17: export function createApp({
18:   canvas,
19:   uiRoot,
20:   gameOverContainer,
21:   writer,
22:   reader,
23: }) {
24:   const GAME_ID = 'flappy-bird';
25:   const MAX_SCORE = 999999;
26: 
27:   const game = createFlappyBird(canvas);
28:   const saveScore = createSaveScore(writer, reader);
29:   const getLeaderboard = createGetLeaderboard(reader);
30: 
31:   let currentNickname = '';
32: 
33:   // ---- utilities ----
34:   function show(el) { el.classList.remove('hidden'); }
35:   function hide(el) { el.classList.add('hidden'); }
36: 
37:   function renderLeaderboard() {
38:     const container = document.getElementById('leaderboard-container');
39:     if (!container) return;
40:     container.innerHTML = '<h3>🏆 Leaderboard</h3>';
41: 
42:     getLeaderboard.execute(GAME_ID, 10).then((entries) => {
43:       if (entries.length === 0) {
44:         container.innerHTML += '<p>Пока нет результатов</p>';
45:         return;
46:       }
47:       const ol = document.createElement('ol');
48:       entries.forEach((e, i) => {
49:         const li = document.createElement('li');
50:         li.textContent = `${e.nickname} — ${e.score}`;
51:         ol.appendChild(li);
52:       });
53:       container.appendChild(ol);
54:     });
55:   }
56: 
57:   // ---- nickname screen ----
58:   const nicknameScreen = document.getElementById('nickname-screen');
59:   const nicknameInput = document.getElementById('nickname-input');
60:   const nicknameBtn = document.getElementById('nickname-btn');
61: 
62:   if (nicknameBtn && nicknameInput) {
63:     nicknameBtn.addEventListener('click', () => {
64:       const raw = nicknameInput.value;
65:       if (raw.trim().length > 0) {
66:         currentNickname = raw.trim();
67:         hide(nicknameScreen);
68:         startGame();
69:       }
70:     });
71:     nicknameInput.addEventListener('keydown', (e) => {
72:       if (e.key === 'Enter') nicknameBtn.click();
73:     });
74:   }
75: 
76:   // ---- game over ----
77:   const gameOverScreen = document.getElementById('gameover-screen');
78:   const finalScoreEl = document.getElementById('final-score');
79:   const saveBtn = document.getElementById('save-score-btn');
80:   const leaderboardContainer = document.getElementById('leaderboard-container');
81: 
82:   let lastScore = 0;
83: 
84:   game.onGameOver((result) => {
85:     lastScore = result.score;
86:     if (finalScoreEl) finalScoreEl.textContent = `Score: ${lastScore}`;
87:     show(gameOverScreen);
88:     // пытаемся сохранить анонимно (без никнейма не сохраняем, только показываем)
89:     renderLeaderboard();
90:   });
91: 
92:   if (saveBtn) {
93:     saveBtn.addEventListener('click', async () => {
94:       if (!currentNickname) return;
95:       saveBtn.disabled = true;
96:       const r = await saveScore.execute(GAME_ID, currentNickname, lastScore, { maxScore: MAX_SCORE });
97:       if (r.ok) {
98:         saveBtn.textContent = '✅ Saved';
99:         renderLeaderboard();
100:       } else {
101:         saveBtn.textContent = `❌ ${r.error}`;
102:       }
103:     });
104:   }
105: 
106:   // ---- start ----
107:   function startGame() {
108:     hide(gameOverScreen);
109:     game.mount(canvas);
110:     game.start();
111:     renderLeaderboard();
112:   }
113: 
114:   // ---- restart ----
115:   const restartBtn = document.getElementById('restart-btn');
116:   if (restartBtn) {
117:     restartBtn.addEventListener('click', () => {
118:       hide(gameOverScreen);
119:       game.dispose();
120:       game.mount(canvas);
121:       game.start();
122:       if (saveBtn) {
123:         saveBtn.disabled = false;
124:         saveBtn.textContent = '💾 Save Score';
125:       }
126:     });
127:   }
128: 
129:   // initial render
130:   renderLeaderboard();
131: }

1: /**
2:  * @file Flappy Bird — реализация IGame для использования через интерфейс
3:  */
4: 
5: /**
6:  * @param {HTMLCanvasElement} canvas
7:  * @returns {import('../../domain/contracts.js').IGame}
8:  */
9: export function createFlappyBird(canvas) {
10:   const ctx = canvas.getContext('2d');
11: 
12:   // ---- constants ----
13:   const W = canvas.width;
14:   const H = canvas.height;
15:   const GRAVITY = 0.45;
16:   const JUMP = -7;
17:   const PIPE_W = 50;
18:   const GAP = 140;
19:   const PIPE_SPEED = 2.8;
20: 
21:   // ---- state ----
22:   let bird = { x: 60, y: H / 2, vy: 0, r: 12 };
23:   let pipes = [];
24:   let score = 0;
25:   let frameId = null;
26:   let running = false;
27:   let paused = false;
28:   let gameOverCallbacks = [];
29: 
30:   let frameCount = 0;
31: 
32:   function reset() {
33:     bird = { x: 60, y: H / 2, vy: 0, r: 12 };
34:     pipes = [];
35:     score = 0;
36:     frameCount = 0;
37:   }
38: 
39:   function onKeyDown(e) {
40:     if (!running || paused) return;
41:     if (e.code === 'Space' || e.key === ' ') {
42:       e.preventDefault();
43:       bird.vy = JUMP;
44:     }
45:   }
46: 
47:   // ---- game loop ----
48:   function loop() {
49:     if (!running || paused) return;
50: 
51:     frameCount++;
52: 
53:     // Add pipes
54:     if (frameCount % 90 === 0) {
55:       const topH = 40 + Math.random() * (H - GAP - 80);
56:       pipes.push({ x: W, topH, bottomY: topH + GAP, scored: false });
57:     }
58: 
59:     // Physics
60:     bird.vy += GRAVITY;
61:     bird.y += bird.vy;
62: 
63:     // Pipes
64:     for (let i = pipes.length - 1; i >= 0; i--) {
65:       const p = pipes[i];
66:       p.x -= PIPE_SPEED;
67: 
68:       if (!p.scored && p.x + PIPE_W < bird.x) {
69:         p.scored = true;
70:         score++;
71:       }
72: 
73:       if (p.x + PIPE_W < 0) {
74:         pipes.splice(i, 1);
75:       }
76:     }
77: 
78:     // Collisions
79:     let dead = false;
80:     if (bird.y + bird.r > H || bird.y - bird.r < 0) dead = true;
81:     for (const p of pipes) {
82:       if (
83:         bird.x + bird.r > p.x &&
84:         bird.x - bird.r < p.x + PIPE_W &&
85:         (bird.y - bird.r < p.topH || bird.y + bird.r > p.bottomY)
86:       ) {
87:         dead = true;
88:         break;
89:       }
90:     }
91: 
92:     if (dead) {
93:       running = false;
94:       gameOverCallbacks.forEach((cb) => cb({ score, gameId: 'flappy-bird' }));
95:       draw();
96:       return;
97:     }
98: 
99:     draw();
100:     frameId = requestAnimationFrame(loop);
101:   }
102: 
103:   function draw() {
104:     ctx.clearRect(0, 0, W, H);
105: 
106:     // Sky
107:     ctx.fillStyle = '#70c5ce';
108:     ctx.fillRect(0, 0, W, H);
109: 
110:     // Pipes
111:     ctx.fillStyle = '#228b22';
112:     for (const p of pipes) {
113:       ctx.fillRect(p.x, 0, PIPE_W, p.topH);
114:       ctx.fillRect(p.x, p.bottomY, PIPE_W, H - p.bottomY);
115:     }
116: 
117:     // Bird
118:     ctx.fillStyle = '#f5c842';
119:     ctx.beginPath();
120:     ctx.arc(bird.x, bird.y, bird.r, 0, Math.PI * 2);
121:     ctx.fill();
122: 
123:     // Score
124:     ctx.fillStyle = '#fff';
125:     ctx.font = '24px monospace';
126:     ctx.textAlign = 'left';
127:     ctx.fillText(`Score: ${score}`, 10, 30);
128:   }
129: 
130:   // ---- public API (IGame) ----
131: 
132:   function mount(canvasEl, input, loop) {
133:     // input и loop — заглушки совместимости; слушаем клавиатуру напрямую
134:     window.addEventListener('keydown', onKeyDown);
135:   }
136: 
137:   function start() {
138:     reset();
139:     running = true;
140:     paused = false;
141:     if (frameId) cancelAnimationFrame(frameId);
142:     loop();
143:   }
144: 
145:   function pause() {
146:     paused = true;
147:   }
148: 
149:   function resume() {
150:     if (running) {
151:       paused = false;
152:       loop();
153:     }
154:   }
155: 
156:   function dispose() {
157:     running = false;
158:     if (frameId) cancelAnimationFrame(frameId);
159:     window.removeEventListener('keydown', onKeyDown);
160:     gameOverCallbacks = [];
161:   }

1: /**
2:  * @file Firebase Firestore leaderboard (модульный, инициализируется через CDN)
3:  */
4: 
5: // Предполагается, что firebase загружен через CDN в window.firebase
6: function getFirestore() {
7:   if (typeof window === 'undefined' || !window.firebase) {
8:     throw new Error('Firebase SDK не загружен. Подключите CDN в index.html');
9:   }
10:   return window.firebase.firestore;
11: }
12: 
13: /**
14:  * @param {object} config — { projectId, apiKey, authDomain, appName? }
15:  * @returns {{ readable: IReadableLeaderboard, writable: IWritableLeaderboard }}
16:  */
17: export function createFirebaseLeaderboard(config) {
18:   const { projectId, apiKey, authDomain } = config;
19:   const appName = config.appName || 'flappy-bird';
20: 
21:   function getApp() {
22:     const firebase = window.firebase;
23:     const apps = firebase.apps;
24:     let app = apps.find((a) => a.name === appName);
25:     if (!app) {
26:       app = firebase.initializeApp({
27:         apiKey,
28:         authDomain,
29:         projectId,
30:       }, appName);
31:     }
32:     return app;
33:   }
34: 
35:   function getDB() {
36:     // __firestore_instance закешируем после первого создания
37:     if (!getDB._instance) {
38:       getDB._instance = getFirestore()(getApp());
39:     }
40:     return getDB._instance;
41:   }
42: 
43:   function scoresCollection(gameId) {
44:     const db = getDB();
45:     return db.collection('scores')
46:       .where('gameId', '==', gameId)
47:       .orderBy('score', 'desc');
48:   }
49: 
50:   /** @type {import('../../domain/contracts.js').IReadableLeaderboard} */
51:   const readable = {
52:     async getScores(gameId, topN = 10) {
53:       if (!gameId) return [];
54:       const snapshot = await scoresCollection(gameId).limit(topN).get();
55:       return snapshot.docs.map((d) => d.data());
56:     },
57:     async getBestScore(gameId) {
58:       if (!gameId) return null;
59:       const snapshot = await scoresCollection(gameId).limit(1).get();
60:       if (snapshot.empty) return null;
61:       return snapshot.docs[0].data().score;
62:     },
63:   };
64: 
65:   /** @type {import('../../domain/contracts.js').IWritableLeaderboard} */
66:   const writable = {
67:     async saveScore(entry) {
68:       const db = getDB();
69:       await db.collection('scores').add(entry);
70:     },
71:   };
72: 
73:   return { readable, writable };
74: }

1: import { TYPES } from '../../domain/contracts.js';
2: 
3: const DB_NAME = 'flappyBirdDB';
4: const STORE_NAME = 'scores';
5: const DB_VERSION = 1;
6: 
7: function openDB() {
8:   return new Promise((resolve, reject) => {
9:     const req = indexedDB.open(DB_NAME, DB_VERSION);
10:     req.onupgradeneeded = () => {
11:       const db = req.result;
12:       if (!db.objectStoreNames.contains(STORE_NAME)) {
13:         const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
14:         store.createIndex('gameId_score', ['gameId', 'score'], { unique: false });
15:       }
16:     };
17:     req.onsuccess = () => resolve(req.result);
18:     req.onerror = () => reject(req.error);
19:   });
20: }
21: 
22: /**
23:  * LocalStorage-реализация IReadableLeaderboard / IWritableLeaderboard
24:  */
25: export function createLocalLeaderboard() {
26:   /** @type {import('../../domain/contracts.js').IReadableLeaderboard} */
27:   const readable = {
28:     async getScores(gameId, topN = 10) {
29:       const db = await openDB();
30:       return new Promise((resolve, reject) => {
31:         const tx = db.transaction(STORE_NAME, 'readonly');
32:         const store = tx.objectStore(STORE_NAME);
33:         const index = store.index('gameId_score');
34:         const range = IDBKeyRange.bound([gameId, 0], [gameId, Infinity]);
35:         const req = index.openCursor(range, 'prev');
36:         const results = [];
37:         req.onsuccess = () => {
38:           const cursor = req.result;
39:           if (cursor && results.length < topN) {
40:             results.push({
41:               nickname: cursor.value.nickname,
42:               score: cursor.value.score,
43:               gameId: cursor.value.gameId,
44:               playedAt: cursor.value.playedAt,
45:             });
46:             cursor.continue();
47:           } else {
48:             resolve(results);
49:           }
50:         };
51:         req.onerror = () => reject(req.error);
52:       });
53:     },
54: 
55:     async getBestScore(gameId) {
56:       const db = await openDB();
57:       return new Promise((resolve, reject) => {
58:         const tx = db.transaction(STORE_NAME, 'readonly');
59:         const store = tx.objectStore(STORE_NAME);
60:         const index = store.index('gameId_score');
61:         const range = IDBKeyRange.bound([gameId, 0], [gameId, Infinity]);
62:         const req = index.openCursor(range, 'prev');
63:         req.onsuccess = () => {
64:           const cursor = req.result;
65:           resolve(cursor ? cursor.value.score : null);
66:         };
67:         req.onerror = () => reject(req.error);
68:       });
69:     },
70:   };
71: 
72:   /** @type {import('../../domain/contracts.js').IWritableLeaderboard} */
73:   const writable = {
74:     async saveScore(entry) {
75:       const db = await openDB();
76:       return new Promise((resolve, reject) => {
77:         const tx = db.transaction(STORE_NAME, 'readwrite');
78:         const store = tx.objectStore(STORE_NAME);
79:         store.add({ ...entry, id: undefined });
80:         tx.oncomplete = () => resolve();
81:         tx.onerror = () => reject(tx.error);
82:       });
83:     },
84:   };
85: 
86:   return { readable, writable };
87: }

1: /**
2:  * @file Доменные правила валидации
3:  */
4: 
5: const NICKNAME_MIN = 1;
6: const NICKNAME_MAX = 16;
7: 
8: /**
9:  * Нормализует и валидирует никнейм.
10:  * @param {string} raw
11:  * @returns {{ ok: true, value: string } | { ok: false, error: string }}
12:  */
13: export function validateNickname(raw) {
14:   if (typeof raw !== 'string') {
15:     return { ok: false, error: 'Никнейм должен быть строкой.' };
16:   }
17:   let val = raw.trim().replace(/\s+/g, ' ');
18:   if (val.length < NICKNAME_MIN || val.length > NICKNAME_MAX) {
19:     return { ok: false, error: `Никнейм от ${NICKNAME_MIN} до ${NICKNAME_MAX} символов.` };
20:   }
21:   // запрещаем управляющие символы
22:   if (/[\x00-\x1F\x7F]/.test(val)) {
23:     return { ok: false, error: 'Никнейм содержит недопустимые символы.' };
24:   }
25:   return { ok: true, value: val };
26: }
27: 
28: /**
29:  * Проверяет, что счёт в допустимом диапазоне.
30:  * @param {number} score
31:  * @param {number} maxScore
32:  * @returns {{ ok: true } | { ok: false, error: string }}
33:  */
34: export function validateScore(score, maxScore) {
35:   if (!Number.isInteger(score) || score < 0 || score > maxScore) {
36:     return { ok: false, error: `Счёт должен быть целым от 0 до ${maxScore}.` };
37:   }
38:   return { ok: true };
39: }

1: /**
2:  * @file GetLeaderboard use case
3:  */
4: 
5: /**
6:  * @param {import('../domain/contracts.js').IReadableLeaderboard} reader
7:  */
8: export function createGetLeaderboard(reader) {
9:   return {
10:     /**
11:      * @param {string} gameId
12:      * @param {number} [topN=10]
13:      * @returns {Promise<import('../domain/ScoreEntry.js').ScoreEntry[]>}
14:      */
15:     async execute(gameId, topN = 10) {
16:       try {
17:         return await reader.getScores(gameId, topN);
18:       } catch {
19:         return [];
20:       }
21:     },
22:   };
23: }

1: /**
2:  * @file SaveScore use case
3:  */
4: import { validateNickname, validateScore } from '../domain/validation.js';
