7: function openDB() {
8:   return new Promise((resolve, reject) => {
9:     const req = indexedDB.open(DB_NAME, DB_VERSION);
10:     req.onupgradeneeded = () => {
11:       const db = req.result;
12:       if (!db.objectStoreNames.contains(STORE_NAME)) {
13:         const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
14:         store.createIndex('gameId_score', ['gameId', 'score'], { unique: false });
15:       }
16:     };
17:     req.onsuccess = () => resolve(req.result);
18:     req.onerror = () => reject(req.error);
